\title{The $L^1$ Bound Integrates to a Fisher--Rao Length Bound}
\author{Aristotle}
\date{22 August 2026}

\begin{document}
\maketitle

\begin{abstract}
We prove that along any smooth curve of strictly positive probability vectors on a finite sample space, the $L^1$ distance between the endpoints is bounded above by the Fisher--Rao length of the curve, with optimal constant $1$. The infinitesimal engine is a single application of the Cauchy--Schwarz inequality on the simplex, $\sum_i |v_i| \le (\sum_i v_i^2/p_i)^{1/2}$, valid because $\sum_i p_i = 1$; integrating this pointwise speed comparison against the fundamental theorem of calculus yields the global statement. We establish a localized version whose hypotheses are imposed only on the interval of integration, and derive the total-variation form: the probability of any event changes by at most half the Fisher--Rao length. We show the inequality is strict for every non-degenerate curve in an exactly solvable two-point family, for which the Fisher--Rao length equals $\arcsin r$ while the $L^1$ displacement equals $r$; the same family shows the constant $1$ is asymptotically attained and therefore optimal. Passing to the square-root (Bhattacharyya) embedding of the simplex into the unit sphere, where the Fisher--Rao speed equals twice the Euclidean speed, we prove a strictly stronger \emph{chord bound}, $\|\sqrt{p(b)}-\sqrt{p(a)}\|_2 \le L/2$, requiring no simplex constraint, and its statistical reformulation $1-\BC(p(a),p(b)) \le L^2/8$. We prove a Pythagorean tensorization identity: squared Fisher--Rao speeds add over independent factors, the cross term vanishing because velocity fields of simplex curves have total mass zero. Finally we establish a smoothness-free discrete analogue: for an arbitrary finite path of probability vectors, the $L^1$ displacement between the endpoints is at most the sum of twice the Bhattacharyya angles of the consecutive steps.
\end{abstract}

\noindent\textbf{Keywords:} Fisher--Rao metric, information geometry, total variation distance, Cauchy--Schwarz inequality, Bhattacharyya coefficient, Hellinger distance, probability simplex, curve length.

\section{Introduction}

\subsection{Two metrics on the space of distributions}

Let $\iota$ be a finite index set with $|\iota| = n$ and let
\[
\Delta^{\circ} = \Big\{ p : \iota \to \R \ \Big|\ p_i > 0 \text{ for all } i,\ \textstyle\sum_i p_i = 1 \Big\}
\]
denote the open probability simplex. Two structures compete for the title of ``the'' distance on $\Delta^\circ$.

The first is extrinsic and operational: the $L^1$ distance $\|p-q\|_1 = \sum_i |p_i - q_i|$, whose half is the total variation distance $\dTV(p,q) = \sup_{S \subseteq \iota}|p(S)-q(S)|$. It is a flat metric --- the restriction of the ambient $\ell^1$ norm --- and it is the natural currency of hypothesis testing, mixing times, and coupling arguments.

The second is intrinsic: the \emph{Fisher--Rao metric}, given at $p$ by
\[
\|v\|_p^2 = \sum_i \frac{v_i^2}{p_i}, \qquad v \in T_p\Delta^\circ = \Big\{v : \textstyle\sum_i v_i = 0\Big\}.
\]
This is the Fisher information of the one-parameter family $p+tv$ at $t=0$; by the Cram\'er--Rao bound it quantifies the local statistical distinguishability of nearby distributions. Uniquely among Riemannian metrics on the simplex it is invariant under sufficient statistics (Chentsov's theorem), which is the precise sense in which it is \emph{the} geometry of statistical inference.

Because the Fisher--Rao metric weights displacement in a coordinate $i$ by $1/p_i$, motion near the boundary of the simplex is expensive: the same $L^1$ increment costs vastly more Fisher--Rao length when it happens in a rare coordinate. A quantitative comparison of the two structures is therefore natural, and this paper supplies it in the strongest form: a \emph{length} comparison with optimal constant, together with several strengthenings and a discretization.

\subsection{Statement of the main result}

For a curve $t \mapsto p(t)$ in $\Delta^\circ$ with velocity field $v(t)$, define the Fisher--Rao speed and length
\[
\sigma(t) = \sqrt{\sum_i \frac{v_i(t)^2}{p_i(t)}}, \qquad L_a^b = \int_a^b \sigma(t)\,dt.
\]

\begin{theorem}[$L^1$--Fisher--Rao length bound]\label{thm:main}
Let $a \le b$, let $p : \R \to (\iota \to \R)$ be such that for every $t$ and $i$ the function $s \mapsto p_i(s)$ is differentiable at $t$ with derivative $v_i(t)$, let each $t \mapsto v_i(t)$ be continuous, and suppose $p_i(t) > 0$ and $\sum_i p_i(t) = 1$ for all $t$. Then
\[
\|p(b)-p(a)\|_1 \;\le\; \int_a^b \sqrt{\sum_i \frac{v_i(t)^2}{p_i(t)}}\; dt.
\]
\end{theorem}

Equivalently, $\dTV(p(a),p(b)) \le \tfrac12 L_a^b$.

\section{Definitions and elementary properties}

Throughout, $\iota$ is a finite index set and all sums $\sum_i$ run over $\iota$.

\begin{definition}[$L^1$ distance]
For $p,q : \iota \to \R$, set $\ell_1(p,q) = \sum_i |p_i - q_i|$.
\end{definition}

\begin{definition}[Fisher--Rao speed]
For $p,v : \iota \to \R$ with $p$ strictly positive, set $\sigma(p,v) = \big(\sum_i v_i^2/p_i\big)^{1/2}$.
\end{definition}

\begin{definition}[Fisher--Rao length]
For a curve $p$ with velocity field $v$ and $a,b \in \R$, set $L(p,v;a,b) = \int_a^b \sigma(p(t),v(t))\,dt$.
\end{definition}

\begin{proposition}
$\ell_1$ is a pseudometric: nonnegative, symmetric, and $\ell_1(p,r) \le \ell_1(p,q) + \ell_1(q,r)$.
\end{proposition}

\begin{proof}
Nonnegativity and symmetry are termwise. For the triangle inequality write $p_i - r_i = (p_i-q_i)+(q_i-r_i)$, apply the scalar triangle inequality coordinatewise, and sum.
\end{proof}

\begin{proposition}
$\sigma(p,v) \ge 0$, and $L(p,v;a,b) \ge 0$ whenever $a \le b$. If the integrand is continuous, the length is additive: $L(p,v;a,b) + L(p,v;b,c) = L(p,v;a,c)$.
\end{proposition}

\begin{proposition}[Total variation is half of $L^1$]\label{prop:tv}
If $\sum_i p_i = \sum_i q_i = 1$ then for every $S \subseteq \iota$,
\[
\Big|\sum_{i\in S}p_i - \sum_{i \in S} q_i\Big| \le \tfrac12 \ell_1(p,q),
\]
with equality for $S = \{i : p_i \ge q_i\}$.
\end{proposition}

\begin{proof}
Let $D = \sum_{i\in S}(p_i-q_i)$ and $D' = \sum_{i \in S^c}(p_i - q_i)$. Since the total masses agree, $D + D' = 0$, so $|D| = |D'|$. By the triangle inequality $|D| \le \sum_{i\in S}|p_i-q_i|$ and $|D| = |D'| \le \sum_{i \in S^c}|p_i-q_i|$; add and halve.
\end{proof}

\section{The main theorem}

\subsection{The infinitesimal bound}

\begin{theorem}[Infinitesimal $L^1 \le$ Fisher--Rao bound]\label{thm:inf}
Let $p : \iota \to \R$ satisfy $p_i > 0$ for all $i$ and $\sum_i p_i = 1$, and let $v : \iota \to \R$ be arbitrary. Then
\[
\sum_i |v_i| \;\le\; \sqrt{\sum_i \frac{v_i^2}{p_i}}.
\]
\end{theorem}

\begin{proof}
Split each summand using strict positivity:
\[
\sum_i |v_i| = \sum_i \Big(\frac{|v_i|}{\sqrt{p_i}}\Big)\big(\sqrt{p_i}\big).
\]
Apply Cauchy--Schwarz to $x_i = |v_i|/\sqrt{p_i}$ and $y_i = \sqrt{p_i}$, in the form $(\sum_i x_iy_i)^2 \le (\sum_i x_i^2)(\sum_i y_i^2)$. Since $x_i^2 = v_i^2/p_i$, $y_i^2 = p_i$, and $\sum_i p_i = 1$, we get $\big(\sum_i|v_i|\big)^2 \le \sum_i v_i^2/p_i$. Both sides being nonnegative, take square roots.
\end{proof}

\begin{remark}
The normalization $\sum_i p_i = 1$ is exactly what makes the constant $1$; for an unnormalized positive weight vector one obtains $\sum_i |v_i| \le \sigma(p,v)\sqrt{\sum_i p_i}$. Equality in Cauchy--Schwarz requires $|v_i| = c\,p_i$; combined with $\sum_i v_i = 0$ this cannot persist along a non-degenerate curve, which is the structural source of the strictness in Section~\ref{sec:sharp}.
\end{remark}

\subsection{Regularity}

\begin{lemma}\label{lem:cont}
Under the hypotheses of Theorem~\ref{thm:main}, each $t \mapsto p_i(t)$ is continuous, and the maps $t \mapsto \sum_i |v_i(t)|$ and $t \mapsto \sigma(p(t),v(t))$ are continuous, hence integrable on compact intervals.
\end{lemma}

\begin{proof}
Differentiability at a point implies continuity there. The first map is a finite sum of continuous functions composed with $|\cdot|$. For the second, each $v_i^2$ is continuous and each $p_i$ is continuous and nonvanishing, so each quotient is continuous; finite sums of continuous functions are continuous and $\sqrt{\cdot}$ is continuous on $[0,\infty)$.
\end{proof}

\subsection{Proof of the main theorem}

\begin{proof}[Proof of Theorem~\ref{thm:main}]
\emph{Step 1 (fundamental theorem of calculus).} For each $i$, $s \mapsto p_i(s)$ has the continuous derivative $v_i$, so $p_i(b)-p_i(a) = \int_a^b v_i(t)\,dt$.

\emph{Step 2 (coordinatewise absolute bound).} Since $a \le b$, $|p_i(b)-p_i(a)| \le \int_a^b |v_i(t)|\,dt$.

\emph{Step 3 (sum and exchange).} Summing over the finite set $\iota$ and exchanging the finite sum with the integral,
\[
\ell_1(p(b),p(a)) \le \sum_i \int_a^b |v_i(t)|\,dt = \int_a^b \sum_i |v_i(t)|\,dt.
\]

\emph{Step 4 (integrate the infinitesimal bound).} By Theorem~\ref{thm:inf} applied at each $t$, $\sum_i |v_i(t)| \le \sigma(p(t),v(t))$. Both sides are continuous by Lemma~\ref{lem:cont}, hence integrable, and monotonicity of the integral over $[a,b]$ gives
\[
\int_a^b \sum_i |v_i(t)|\,dt \le \int_a^b \sigma(p(t),v(t))\,dt = L(p,v;a,b). \qedhere
\]
\end{proof}

\subsection{Localization}

Theorem~\ref{thm:main} asks for a globally defined positive probability curve, a genuine restriction: a straight segment $t \mapsto (1-t)p + tq$, extended to all of $\R$, leaves the simplex in finite time.

\begin{theorem}[Localized length bound]\label{thm:loc}
Let $a \le b$. Suppose that for every $t \in [a,b]$ and every $i$: the map $s \mapsto p_i(s)$ is differentiable at $t$ with derivative $v_i(t)$; each $t \mapsto v_i(t)$ is continuous on $[a,b]$; $p_i(t)>0$; and $\sum_i p_i(t)=1$. Then $\ell_1(p(b),p(a)) \le L(p,v;a,b)$.
\end{theorem}

\begin{proof}
Identical to the proof of Theorem~\ref{thm:main}, with continuity replaced by continuity on $[a,b]$ throughout: the $p_i$ are continuous on $[a,b]$ because differentiable there, the quotients $v_i^2/p_i$ are continuous there because the denominators do not vanish, the fundamental theorem of calculus applies with derivative hypotheses on $[a,b]$, and Theorem~\ref{thm:inf} is invoked only at $t \in [a,b]$.
\end{proof}

The positivity requirement is not a technicality: if the curve touches the boundary, $v_i^2/p_i$ can be non-integrable and the Fisher--Rao length genuinely infinite, while the $L^1$ displacement remains bounded by $2$.

\subsection{Total-variation and event forms}

\begin{corollary}
Under the hypotheses of Theorem~\ref{thm:main}, $\dTV(p(a),p(b)) = \tfrac12\ell_1(p(b),p(a)) \le \tfrac12 L(p,v;a,b)$.
\end{corollary}

\begin{corollary}[No event moves far]\label{cor:event}
Under the hypotheses of Theorem~\ref{thm:main}, for every $S \subseteq \iota$,
\[
\Big|\sum_{i\in S}p_i(b) - \sum_{i \in S}p_i(a)\Big| \le \tfrac12 L(p,v;a,b).
\]
\end{corollary}

\begin{proof}
Combine Proposition~\ref{prop:tv} with Theorem~\ref{thm:main}.
\end{proof}

\section{Sharpness: an exactly solvable family}\label{sec:sharp}

\begin{definition}
For $r \in [0,1)$ define, on the two-point set,
\[
p^{(r)}(t) = \Big(\frac{1+r\sin t}{2},\ \frac{1-r\sin t}{2}\Big), \qquad v^{(r)}(t) = \Big(\frac{r\cos t}{2},\ -\frac{r\cos t}{2}\Big).
\]
\end{definition}

Then $v^{(r)}$ is the velocity field of $p^{(r)}$, the coordinates sum to $1$, and both are strictly positive since $|r\sin t| \le |r| < 1$.

\begin{lemma}[Speed]\label{lem:speed}
For $|r|<1$ and $r \cos t \ge 0$,
\[
\sigma\big(p^{(r)}(t),v^{(r)}(t)\big) = \frac{r\cos t}{\sqrt{1-r^2\sin^2 t}}.
\]
\end{lemma}

\begin{proof}
With $u = r\sin t$,
\[
\sum_i \frac{v_i^2}{p_i} = \frac{(r\cos t)^2}{2}\Big(\frac{1}{1+u}+\frac{1}{1-u}\Big) = \frac{(r\cos t)^2}{1-u^2}. \qedhere
\]
\end{proof}

\begin{theorem}[Exact length]\label{thm:arcsin}
For $0 \le r < 1$,
\[
L\big(p^{(r)},v^{(r)};0,\tfrac\pi2\big) = \arcsin r, \qquad \ell_1\big(p^{(r)}(\tfrac\pi2),p^{(r)}(0)\big) = r.
\]
\end{theorem}

\begin{proof}
On $[0,\pi/2]$ we have $\cos t \ge 0$, so by Lemma~\ref{lem:speed} the length is $\int_0^{\pi/2} r\cos t\,(1-r^2\sin^2t)^{-1/2}dt$. By the chain rule the integrand is $\frac{d}{dt}\arcsin(r\sin t)$ (legitimate since $|r\sin t|<1$), so the integral is $\arcsin r - \arcsin 0 = \arcsin r$. The endpoints are $(\tfrac12,\tfrac12)$ and $(\tfrac{1+r}{2},\tfrac{1-r}{2})$, so the $L^1$ displacement is $r/2 + r/2 = r$.
\end{proof}

Theorem~\ref{thm:main} applied to this family reads $r \le \arcsin r$ --- the classical elementary inequality, recovered as an instance of information geometry.

\begin{corollary}[Strictness]
For $0 < r < 1$ the inequality of Theorem~\ref{thm:main} is strict on this family.
\end{corollary}

\begin{proof}
With $\theta = \arcsin r > 0$, strict concavity gives $\sin\theta < \theta$, i.e.\ $r < \arcsin r$.
\end{proof}

\begin{corollary}[Optimality of the constant]
For every $\varepsilon>0$ there is $r \in (0,1)$ with $L\big(p^{(r)},v^{(r)};0,\tfrac\pi2\big) \le (1+\varepsilon)\,\ell_1\big(p^{(r)}(\tfrac\pi2),p^{(r)}(0)\big)$. Hence no constant $c<1$ satisfies $\ell_1 \le c L$ for all curves.
\end{corollary}

\begin{proof}
Put $d = \min\{1,\sqrt\varepsilon\}$ and $r = \sin d \in (0,1)$, so $\arcsin r = d$. It suffices that $d \le (1+\varepsilon)\sin d$. Using $\sin d > d - d^3/4$ for $0<d\le1$, it is enough that $(1+\varepsilon)d^2/4 \le \varepsilon$. For $\varepsilon \le 3$ this follows from $d^2 \le \varepsilon$; for $\varepsilon \ge 1$ we have $d = 1$ and $(1+\varepsilon)/4 \le \varepsilon$.
\end{proof}

The ratio $\arcsin r/r$ increases from $1$ as $r \to 0^+$ to $\pi/2 \approx 1.5708$ as $r \to 1^-$: the deficit is second order for short curves.

\section{The square-root embedding and the chord bound}

\subsection{The simplex as a piece of a sphere}

\begin{definition}
The \emph{square-root embedding} is $\Phi(p)_i = \sqrt{p_i}$. For $p_i \ge 0$ with $\sum_i p_i = 1$ we have $\sum_i \Phi(p)_i^2 = 1$: it maps the simplex onto the nonnegative orthant of the unit sphere. For $p$ strictly positive with velocity $v$, the \emph{square-root velocity} is $\widetilde v_i = v_i/(2\sqrt{p_i})$, which is $\frac{d}{dt}\sqrt{p_i(t)}$.
\end{definition}

\begin{theorem}[Fisher--Rao is round]\label{thm:round}
For $p$ strictly positive, $\sigma(p,v) = 2\big(\sum_i \widetilde v_i^{\,2}\big)^{1/2}$: the Fisher--Rao speed is exactly twice the Euclidean speed of the square-root curve.
\end{theorem}

\begin{proof}
$\widetilde v_i^{\,2} = v_i^2/(4p_i)$, so $\sum_i \widetilde v_i^{\,2} = \tfrac14\sum_i v_i^2/p_i$.
\end{proof}

\subsection{The chord bound}

\begin{theorem}[Chord bound]\label{thm:chord}
Let $a \le b$, let $p$ have continuous velocity field $v$ and satisfy $p_i(t)>0$ for all $t,i$. Then
\[
\big\|\Phi(p(b)) - \Phi(p(a))\big\|_2 \;\le\; \tfrac12 L(p,v;a,b).
\]
No normalization hypothesis is required: this is a purely metric statement.
\end{theorem}

\begin{proof}
Let $\Delta_i = \sqrt{p_i(b)}-\sqrt{p_i(a)}$ and $D = \|\Delta\|_2$. If $D=0$ the claim is nonnegativity of the length; assume $D>0$ and set
\[
g(t) = \frac1D \sum_i \Delta_i \sqrt{p_i(t)},
\]
a \emph{scalar} test function, which replaces vector-valued integration by ordinary one-dimensional calculus.

\emph{Endpoints.} $g(b)-g(a) = \frac1D\sum_i\Delta_i^2 = D$.

\emph{Derivative.} $g'(t) = \frac1D\sum_i \Delta_i \widetilde v_i(t)$, continuous.

\emph{Pointwise bound.} By Cauchy--Schwarz and Theorem~\ref{thm:round},
\[
\Big|\sum_i \Delta_i\widetilde v_i(t)\Big| \le D\Big(\sum_i \widetilde v_i(t)^2\Big)^{1/2} = D\cdot\tfrac12\sigma(p(t),v(t)),
\]
so $g'(t) \le \tfrac12\sigma(p(t),v(t))$.

\emph{Integration.} By the fundamental theorem of calculus and monotonicity,
$D = \int_a^b g'(t)\,dt \le \tfrac12 L(p,v;a,b)$.
\end{proof}

Theorem~\ref{thm:chord} is strictly stronger than Theorem~\ref{thm:main} for short curves. Indeed the coordinatewise inequality $(\sqrt x - \sqrt y)^2 \le |x-y|$ for $x,y \ge 0$ --- which follows from $|x-y| = |\sqrt x - \sqrt y|(\sqrt x + \sqrt y)$ --- gives $\sum_i(\sqrt{p_i}-\sqrt{q_i})^2 \le \ell_1(p,q)$, so twice the squared Hellinger distance is at most the $L^1$ distance; combining with Theorem~\ref{thm:main} yields only the linear bound $H^2 \le \tfrac12 L$, whereas Theorem~\ref{thm:chord} gives the following quadratic one.

\subsection{Hellinger and Bhattacharyya forms}

\begin{definition}
The \emph{Bhattacharyya coefficient} is $\BC(p,q) = \sum_i\sqrt{p_iq_i} = \langle \Phi(p),\Phi(q)\rangle$, the cosine of the spherical angle between the square-root embeddings. The squared Hellinger distance is $H^2(p,q) = \tfrac12\sum_i(\sqrt{p_i}-\sqrt{q_i})^2 = 1-\BC(p,q)$.
\end{definition}

\begin{theorem}[Quadratic overlap bound]\label{thm:quad}
Under the hypotheses of Theorem~\ref{thm:main},
\[
1 - \BC\big(p(a),p(b)\big) \le \tfrac18 L(p,v;a,b)^2.
\]
\end{theorem}

\begin{proof}
For normalized endpoints, $\sum_i(\sqrt{p_i(b)}-\sqrt{p_i(a)})^2 = 2 - 2\BC(p(a),p(b))$. Squaring the nonnegative chord bound of Theorem~\ref{thm:chord} gives $2-2\BC \le \tfrac14 L^2$.
\end{proof}

On the family of Section~\ref{sec:sharp} the endpoints give $\BC = \tfrac12(\sqrt{1+r}+\sqrt{1-r})$, hence $1-\BC = r^2/8 + O(r^4)$, while $L^2/8 = (\arcsin r)^2/8 = r^2/8 + O(r^4)$: the chord bound is asymptotically tight as well.

\section{Tensorization: Fisher--Rao is Pythagorean}

\begin{lemma}[Velocities are traceless]\label{lem:traceless}
If $t \mapsto p(t)$ is differentiable with velocity $v(t)$ and $\sum_i p_i(t) = 1$ for all $t$, then $\sum_i v_i(t)=0$.
\end{lemma}

\begin{proof}
The map $s \mapsto \sum_i p_i(s)$ is constant, so its derivative vanishes; by linearity that derivative is $\sum_i v_i(t)$.
\end{proof}

\begin{theorem}[Pythagorean tensorization]\label{thm:tensor}
Let $p$ and $q$ be strictly positive probability vectors on $\iota$ and $\kappa$, and let $v,w$ be tangent vectors with $\sum_j w_j = 0$. For the product point $(p\otimes q)_{(i,j)} = p_iq_j$ with velocity $v_iq_j + p_iw_j$,
\[
\sum_{(i,j)}\frac{(v_iq_j+p_iw_j)^2}{p_iq_j} = \sum_i \frac{v_i^2}{p_i} + \sum_j\frac{w_j^2}{q_j},
\]
equivalently $\sigma(p\otimes q, v\otimes q + p \otimes w) = \sqrt{\sigma(p,v)^2+\sigma(q,w)^2}$.
\end{theorem}

\begin{proof}
Coordinatewise,
\[
\frac{(v_iq_j+p_iw_j)^2}{p_iq_j} = \frac{v_i^2}{p_i}q_j + 2v_iw_j + p_i\frac{w_j^2}{q_j}.
\]
Summing over $j$ with $\sum_j q_j=1$ and $\sum_j w_j = 0$ kills the cross term and leaves $v_i^2/p_i + p_i\sum_j w_j^2/q_j$; summing over $i$ with $\sum_i p_i = 1$ gives the identity.
\end{proof}

The vanishing of the cross term is exactly conservation of probability (Lemma~\ref{lem:traceless}): independence turns the metric into an orthogonal direct sum.

\section{The discrete, smoothness-free analogue}

\begin{theorem}[Le Cam's inequality]\label{thm:lecam}
For probability vectors $p,q$ on $\iota$, $\ell_1(p,q) \le 2\sqrt{1-\BC(p,q)^2}$.
\end{theorem}

\begin{proof}
Factor $|p_i-q_i| = |\sqrt{p_i}-\sqrt{q_i}|(\sqrt{p_i}+\sqrt{q_i})$ and apply Cauchy--Schwarz:
\[
\ell_1(p,q)^2 \le \Big(\sum_i(\sqrt{p_i}-\sqrt{q_i})^2\Big)\Big(\sum_i(\sqrt{p_i}+\sqrt{q_i})^2\Big) = (2-2\BC)(2+2\BC) = 4(1-\BC^2),
\]
using $\sum_i(\sqrt{p_i}\mp\sqrt{q_i})^2 = 2\mp2\BC$.
\end{proof}

\begin{corollary}[Single-step angular bound]\label{cor:angle}
$\ell_1(p,q) \le 2\arccos\BC(p,q)$.
\end{corollary}

\begin{proof}
With $\theta = \arccos\BC \in [0,\pi/2]$ we have $\sqrt{1-\BC^2} = \sin\theta \le \theta$.
\end{proof}

The quantity $\arccos\BC(p,q)$ is the geodesic distance between $\Phi(p)$ and $\Phi(q)$ on the unit sphere; twice it is the Fisher--Rao geodesic distance in the present normalization, consistent with the factor $2$ of Theorem~\ref{thm:round}.

\begin{theorem}[Discrete Fisher--Rao length bound]\label{thm:discrete}
Let $p^{(0)},\dots,p^{(N)}$ be any finite sequence of probability vectors on $\iota$. Then
\[
\ell_1\big(p^{(N)},p^{(0)}\big) \le \sum_{k=0}^{N-1} 2\arccos\BC\big(p^{(k)},p^{(k+1)}\big).
\]
\end{theorem}

\begin{proof}
Induction on $N$. For $N=0$ both sides vanish. For the step, the triangle inequality gives $\ell_1(p^{(N+1)},p^{(0)}) \le \ell_1(p^{(N+1)},p^{(N)}) + \ell_1(p^{(N)},p^{(0)})$; bound the first term by Corollary~\ref{cor:angle} and the second by the inductive hypothesis.
\end{proof}

Theorem~\ref{thm:discrete} requires no derivative, no interval, and no strict positivity; it applies verbatim to a Markov chain trajectory or to the iterates of an optimization algorithm. In the smooth case, refining the partition makes the right-hand side converge to the Fisher--Rao length, so Theorem~\ref{thm:discrete} contains Theorem~\ref{thm:main} in the limit.

\section{Algorithms}

\paragraph{Fisher--Rao length by quadrature.} Evaluate $\sigma(p(t),v(t))$ at quadrature nodes and sum. With the midpoint rule on $n$ subintervals and $|\iota| = m$, the cost is $\Theta(nm)$ and the error $O(n^{-2})$ for a $C^2$ integrand. The integrand degrades sharply as $\min_i p_i(t)\to0$; adaptive refinement is then essential.

\paragraph{Discrete length via Bhattacharyya angles.} Compute $\BC(p^{(k)},p^{(k+1)})$ for consecutive pairs, take $\arccos$, and sum with weight $2$; cost $\Theta(Nm)$. Since $\arccos$ loses precision when $\BC \approx 1$, it is more accurate to compute the chord $c = \|\Phi(p)-\Phi(q)\|_2$ and use $2\arcsin(c/2)$.

\paragraph{Certified bound checking.} Compute $\ell_1$, the chord, and $L$ simultaneously and verify $\ell_1 \le L$, $\text{chord} \le L/2$, and $1-\BC \le L^2/8$; for the family of Section~\ref{sec:sharp}, check against the closed forms $\ell_1 = r$, $L = \arcsin r$.

\section{Applications and discussion}

\paragraph{Sample complexity.} Fisher information is the local currency of statistical distinguishability. Corollary~\ref{cor:event} converts a budget on Fisher--Rao length into a hard, non-asymptotic guarantee: no event's probability changes by more than $L/2$.

\paragraph{Optimization on the simplex.} Natural gradient descent, entropic mirror descent, and replicator dynamics trace curves whose intrinsic length is the Fisher--Rao length. Theorem~\ref{thm:main} translates a bound on cumulative natural-gradient work into a bound on total-variation displacement of the model; Theorem~\ref{thm:quad} sharpens this quadratically for small steps, and Theorem~\ref{thm:discrete} applies directly to discrete iterates.

\paragraph{Markov chains.} Theorem~\ref{thm:discrete} bounds total-variation displacement of a chain by an accumulation of per-step Bhattacharyya angles, computable from consecutive laws alone.

\paragraph{Quantum speed limits.} The square-root embedding is the passage from a classical distribution to a real nonnegative amplitude vector, and Fisher--Rao length is Fubini--Study length on that slice; Theorem~\ref{thm:chord} is the classical shadow of a Mandelstam--Tamm-type statement, and Theorem~\ref{thm:tensor} mirrors additivity of quantum Fisher information over subsystems.

\paragraph{Limitations.} Strict positivity and normalization along the curve are essential. Positivity fails for curves touching the boundary, where the length may diverge; Theorem~\ref{thm:loc} is the right tool when positivity holds only on the interval of interest. Normalization fixes the constant at $1$. The results are stated for a finite sample space.

\section{Future directions}

\begin{enumerate}
\item \textbf{Infinite sample spaces.} Define the Fisher--Rao speed of a curve of densities as $\|\dot p_t/\sqrt{p_t}\|_{L^2}$; the Cauchy--Schwarz step is unchanged, and the work lies in absolute continuity and differentiation under the integral sign.
\item \textbf{Geodesic completion.} The Fisher--Rao geodesic distance is $2\arccos\BC(p,q)$; prove directly that great-circle arcs minimize length and deduce the main theorem from the sharp inequality of Corollary~\ref{cor:angle}.
\item \textbf{Equality analysis.} Characterize asymptotically tight curves; the equality condition $|v_i| = c\,p_i$ with $\sum_i v_i = 0$ suggests infinitesimal two-point excursions are the only ones.
\item \textbf{Curvature refinements.} Quantify the deficit $\tfrac12 L - \|\Phi(p(b))-\Phi(p(a))\|_2$ in terms of the turning of the curve.
\item \textbf{Higher-order divergence bounds.} Extend $1-\BC \le L^2/8$ to $f$-divergences with $D_f \le c_f L^2$, $c_f$ determined by $f''(1)$.
\item \textbf{Algorithmic guarantees.} Turn the main theorem into explicit stability certificates for natural gradient and mirror descent.
\end{enumerate}

\section{Conclusion}

The $L^1$ distance and the Fisher--Rao metric are the flat and curved faces of the same object. The curved face always dominates, at the level of lengths, with optimal constant $1$; the inequality is nevertheless strict off the trivial case; it refines, through the square-root embedding, into a spherical chord bound and a quadratic overlap bound; it tensorizes Pythagoreanly; and it persists, in exact discrete form, when all smoothness is discarded. The proof of the central inequality is a single application of Cauchy--Schwarz to the splitting $|v_i| = (|v_i|/\sqrt{p_i})\sqrt{p_i}$, made possible by the one fact that defines the simplex: probabilities sum to one.

\end{document}

