"""Adaptive quadrature for the Fisher-Rao length of a curve in the simplex."""

from __future__ import annotations

import math
from typing import Callable, List, Sequence, Tuple

Vector = Sequence[float]
Curve = Callable[[float], Vector]


def fisher_rao_speed(p: Vector, v: Vector) -> float:
    """Fisher-Rao norm sqrt(sum_i v_i^2 / p_i); requires p strictly positive."""
    if any(pi <= 0.0 for pi in p):
        raise ValueError("point leaves the open simplex: Fisher-Rao speed undefined")
    return math.sqrt(sum(vi * vi / pi for pi, vi in zip(p, v)))


def _simpson(f: Callable[[float], float], a: float, b: float) -> float:
    """Simpson's rule on a single panel [a, b]."""
    m = 0.5 * (a + b)
    return (b - a) / 6.0 * (f(a) + 4.0 * f(m) + f(b))


def _adaptive(f: Callable[[float], float], a: float, b: float,
              whole: float, tol: float, depth: int) -> float:
    """Recursive adaptive Simpson with Richardson error control."""
    m = 0.5 * (a + b)
    left = _simpson(f, a, m)
    right = _simpson(f, m, b)
    if depth <= 0 or abs(left + right - whole) <= 15.0 * tol:
        return left + right + (left + right - whole) / 15.0
    return (_adaptive(f, a, m, left, tol / 2.0, depth - 1)
            + _adaptive(f, m, b, right, tol / 2.0, depth - 1))


def fisher_rao_length(p: Curve, v: Curve, a: float, b: float,
                      tol: float = 1e-12, max_depth: int = 60) -> float:
    """Fisher-Rao length int_a^b sqrt(sum_i v_i(t)^2 / p_i(t)) dt.

    Adaptive Simpson concentrates nodes where the integrand varies fastest --
    exactly the regions where the curve approaches the boundary of the simplex
    and the integrand v_i^2 / p_i becomes large. Cost is O(N * m) integrand
    evaluations for N adaptively chosen panels and m outcomes; the error for a
    C^4 integrand is O(h^4) per panel.
    """
    if b < a:
        return -fisher_rao_length(p, v, b, a, tol, max_depth)

    def f(t: float) -> float:
        return fisher_rao_speed(p(t), v(t))

    return _adaptive(f, a, b, _simpson(f, a, b), tol, max_depth)


def min_coordinate(p: Curve, a: float, b: float, samples: int = 1001) -> Tuple[float, float]:
    """Smallest coordinate encountered on a uniform grid, with its location.

    A diagnostic: the Fisher-Rao length blows up as this value approaches 0.
    """
    best_t, best = a, float("inf")
    for k in range(samples):
        t = a + (b - a) * k / (samples - 1)
        m = min(p(t))
        if m < best:
            best, best_t = m, t
    return best, best_t


if __name__ == "__main__":
    def curve(r: float) -> Curve:
        return lambda t: [(1 + r * math.sin(t)) / 2, (1 - r * math.sin(t)) / 2]

    def vel(r: float) -> Curve:
        return lambda t: [r * math.cos(t) / 2, -r * math.cos(t) / 2]

    header: List[str] = ["r", "adaptive length", "arcsin r", "abs error"]
    print("{:>8}{:>18}{:>14}{:>13}".format(*header))
    for r in (0.1, 0.5, 0.9, 0.999):
        got = fisher_rao_length(curve(r), vel(r), 0.0, math.pi / 2)
        exact = math.asin(r)
        print(f"{r:>8.3f}{got:>18.12f}{exact:>14.9f}{abs(got - exact):>13.3e}")

