    return 2 * arcsin( min(1, c/2) )      // stable form of arccos BC(p,q)

function DISCRETE_FISHER_RAO_LENGTH(path p^(0..N)):
    L <- 0
    for k <- 0 to N-1:
        L <- L + 2 * BHATTACHARYYA_ANGLE(p^(k), p^(k+1))
    return L

