"""Discrete Fisher-Rao length of a finite path of probability vectors."""

from __future__ import annotations

import math
from typing import List, Sequence

Vector = Sequence[float]


def bhattacharyya(p: Vector, q: Vector) -> float:
    """BC(p, q) = sum_i sqrt(p_i q_i), the cosine of the spherical angle."""
    return sum(math.sqrt(max(pi, 0.0) * max(qi, 0.0)) for pi, qi in zip(p, q))


def sqrt_chord(p: Vector, q: Vector) -> float:
    """Euclidean chord ||sqrt(p) - sqrt(q)||_2 of the square-root embedding."""
    return math.sqrt(sum((math.sqrt(max(pi, 0.0)) - math.sqrt(max(qi, 0.0))) ** 2
                         for pi, qi in zip(p, q)))


def bhattacharyya_angle(p: Vector, q: Vector) -> float:
    """Spherical distance arccos BC(p, q), evaluated in a stable way.

    Computing arccos(BC) directly loses roughly half the significant digits when
    BC is close to 1, i.e. for nearby distributions -- precisely the regime of a
    finely refined path. The chord c = ||sqrt(p) - sqrt(q)||_2 satisfies
    c = 2 sin(theta / 2), so theta = 2 arcsin(c / 2) is well-conditioned there.
    """
    c = sqrt_chord(p, q)
    return 2.0 * math.asin(min(1.0, 0.5 * c))


def discrete_fisher_rao_length(path: Sequence[Vector]) -> float:
    """Sum over consecutive steps of twice the Bhattacharyya angle.

    This is the discrete Fisher-Rao length of the path: for a smooth curve it
    converges monotonically upward to the integral length as the partition is
    refined, and it bounds the L1 displacement of the endpoints with no
    smoothness hypothesis whatsoever. Cost: O(N * m) for N steps, m outcomes.
    """
    return sum(2.0 * bhattacharyya_angle(path[k], path[k + 1])
               for k in range(len(path) - 1))


def l1_distance(p: Vector, q: Vector) -> float:
    """L1 distance sum_i |p_i - q_i|."""
    return sum(abs(pi - qi) for pi, qi in zip(p, q))


def certificate(path: Sequence[Vector]) -> dict:
    """Return the endpoint L1 displacement, the discrete length, and the slack."""
    length = discrete_fisher_rao_length(path)
    l1 = l1_distance(path[-1], path[0])
    return {"l1": l1, "discrete_length": length, "slack": length - l1,
            "holds": l1 <= length + 1e-12}


if __name__ == "__main__":
    path: List[List[float]] = [
        [0.50, 0.30, 0.20],
        [0.20, 0.55, 0.25],
        [0.60, 0.10, 0.30],
        [0.15, 0.15, 0.70],
    ]
    for key, value in certificate(path).items():
        print(f"{key:>18}: {value}")

