function GEODESIC(p, q):
    a <- sqrt(p);  b <- sqrt(q)                 // amplitude vectors on the sphere
    theta <- arccos( clamp( <a, b>, -1, 1 ) )   // <a,b> = BC(p,q)
    return function gamma(s in [0,1]):
        if theta < eps:
            amp <- (1-s) a + s b                 // degenerate: linear fallback
        else:
            amp <- ( sin((1-s) theta) a + sin(s theta) b ) / sin(theta)
        raw <- componentwise amp^2
        return raw / sum(raw)                    // renormalize against roundoff

function GEODESIC_DISTANCE(p, q):
    return 2 * arccos( clamp( BC(p,q), -1, 1 ) )

function POLYLINE_LENGTH(gamma, n):
    L <- 0;  prev <- gamma(0)
    for k <- 1 to n:
        cur <- gamma(k/n)
        L   <- L + 2 * BHATTACHARYYA_ANGLE(prev, cur)
        prev <- cur
    return L
